    ): Session =
        api(passkey, null, emptySet()).accounts.registerFinish(registerFinishRequest = RegisterFinishRequest(challengeId = challengeId, registration = registration, invite = invite, holderKey = holderKey))

    /**
     * End one session
     *
     * `404` for a session the account does not hold live.
     *
     * **Who:** an account holder (a passkey session not bound to an app's frontend).
     *
     * `DELETE /auth/sessions/{session}` (`session_revoke`).
     *
     * @throws com.calimero.mero.CalimeroError the node's refusal, typed by [com.calimero.mero.errorFrom].
     */
    suspend fun sessionRevoke(
        session: kotlin.String,
    ): kotlinx.serialization.json.JsonObject =
        api(null, null, emptySet()).accounts.sessionRevoke(session = session)

    /**
     * The account's live sessions
     *
     * Latest active first, at most 256. `openedAt` (Unix seconds) is `null` for a session opened before the node kept it.
     *
     * **Who:** an account holder (a passkey session not bound to an app's frontend).
     *
     * `GET /auth/sessions` (`sessions_list`).
     *
     * @throws com.calimero.mero.CalimeroError the node's refusal, typed by [com.calimero.mero.errorFrom].
     */
    suspend fun sessionsList(): SessionList =
        api(null, null, emptySet()).accounts.sessionsList()

    /**
     * The account's usage against its quotas
     *
     * The apps the account owns, its bundle bytes (a decimal string), API keys and owned organizations; the file bytes held by each payer it belongs to (each organization it is in, and `account:<id>` for its own apps); the cluster's quotas; and what today's runs of the apps the account develops used (decimal strings).
     *
     * **Who:** signed in (a session or an API key).
     *
     * `GET /auth/usage` (`usage`).
     *
     * @throws com.calimero.mero.CalimeroError the node's refusal, typed by [com.calimero.mero.errorFrom].
     */
    suspend fun usage(): AccountUsage =
        api(null, null, emptySet()).accounts.usage()
}
